 "content": "def transform(grid):
    """Repeat the motif from the marked tile, recolored by each tile-row marker."""
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if grid[r] and grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(n, separators):
        cuts = [-1] + separators + [n]
        return [(cuts[i] + 1, cuts[i + 1]) for i in range(len(cuts) - 1) if cuts[i + 1] - cuts[i] > 1]

    bands = spans(h, sep_rows)
    tiles = spans(w, sep_cols)
    # Find the one nonempty non-marker tile; its occupied coordinates define the motif.
    motif = None
    for br, (r0, r1) in enumerate(bands):
        for bc, (c0, c1) in enumerate(tiles):
            if bc == 0:
                continue
            points = [(r-r0, c-c0, grid[r][c])
                      for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0]
            if points:
                motif = [(dr, dc) for dr, dc, _ in points]
                break
        if motif is not None:
            break
    if motif is None:
        raise ValueError('No motif tile found')

    out = [row[:] for row in grid]
    for br, (r0, r1) in enumerate(bands):
        c0, c1 = tiles[0]
        colors = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0]
        if not colors:
            raise ValueError('No row marker found')
        color = max(set(colors), key=colors.count)
        for c0, c1 in tiles:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            for dr, dc in motif:
                if dr < r1-r0 and dc < c1-c0:
                    out[r0+dr][c0+dc] = color
    return out
